  "2 cycles": { hi: "2 साइकल", gu: "2 સાયકલ" },
  "3 cycles": { hi: "3 साइकल", gu: "3 સાયકલ" },
  "4+ cycles (budget planning)": { hi: "4+ साइकल (बजट योजना)", gu: "4+ સાયકલ (બજેટ આયોજન)" },
  "Add-Ons": { hi: "ऐड-ऑन", gu: "એડ-ઓન" },
