  "PCOS / Ovulatory disorder": { hi: "PCOS / ओव्यूलेटरी विकार", gu: "PCOS / ઓવ્યુલેટરી ડિસઓર્ડર" },
  "Tubal factor": { hi: "ट्यूबल कारक", gu: "ટ્યુબલ પરિબળ" },
