  "Severe male factor (azoospermia)": { hi: "गंभीर पुरुष कारक (एज़ोस्पर्मिया)", gu: "ગંભીર પુરુષ પરિબળ (એઝોસ્પર્મિયા)" },
  "Endometriosis": { hi: "एंडोमेट्रियोसिस", gu: "એન્ડોમેટ્રિઓસિસ" },
  "Diminished ovarian reserve": { hi: "कम ओवेरियन रिज़र्व", gu: "ઘટેલ ઓવેરિયન રિઝર્વ" },
