  "Preimplantation Genetic Testing (PGT)": { hi: "प्रीइम्प्लांटेशन जेनेटिक टेस्टिंग (PGT)", gu: "પ્રીઇમ્પ્લાન્ટેશન જિનેટિક ટેસ્ટિંગ (PGT)" },
